#pragma once
#include <string>
#include <vector>

// ---------------------------------------------------------------------------
// Token types
// ---------------------------------------------------------------------------
enum class TokenKind {
    // Literals
    Number, String, TemplateString, Identifier, Regex,

    // Keywords (subset needed for JSX context detection)
    KW_return, KW_import, KW_export, KW_default, KW_function,
    KW_const, KW_let, KW_var, KW_from, KW_as,
    KW_if, KW_else, KW_for, KW_while, KW_do,
    KW_new, KW_typeof, KW_void, KW_delete, KW_in, KW_instanceof,
    KW_class, KW_extends, KW_this, KW_super, KW_null, KW_true, KW_false,
    KW_arrow,         // =>
    KW_async, KW_await,

    // Punctuation
    LParen, RParen, LBrace, RBrace, LBracket, RBracket,
    Semicolon, Colon, Comma, Dot, DotDotDot, QuestionMark,
    Equals,           // =
    EqualsEquals, BangEquals, EqualsEqualsEquals, BangEqualsEquals,
    PlusEquals, MinusEquals, StarEquals, SlashEquals,
    AmpAmp, PipePipe, QuestionQuestion,
    Plus, Minus, Star, Slash, Percent, Bang,
    Amp, Pipe, Caret, Tilde, LShift, RShift, URShift,
    Less, Greater, LessEquals, GreaterEquals,
    PlusPlus, MinusMinus,
    Backquote,

    // JSX-specific
    JSXLess,          // < that opens a JSX element
    JSXGreater,       // >
    JSXSlash,         // / inside JSX tag
    JSXText,          // raw text between JSX tags
    JSXLBrace,        // { inside JSX (enter expression)
    JSXRBrace,        // } exits expression back to JSX
    JSXString,        // attribute string literal in JSX

    // Meta
    EndOfFile,
    Unknown,
};

struct Token {
    TokenKind kind;
    std::string value;
    int line;
    int col;
};

// ---------------------------------------------------------------------------
// LexMode controls whether we tokenise JS or JSX content
// ---------------------------------------------------------------------------
enum class LexMode { JS, JSXTag, JSXChildren };

class Lexer {
public:
    explicit Lexer(std::string source);

    // Produce all tokens eagerly (simpler for recursive-descent parser)
    std::vector<Token> tokenize();

private:
    std::string src_;
    size_t pos_  = 0;
    int    line_ = 1;
    int    col_  = 1;

    // ---- character helpers ----
    char peek(int offset = 0) const;
    char advance();
    bool atEnd() const;
    void skipWhitespaceAndComments();

    // ---- JS token scanners ----
    Token scanNumber();
    Token scanString(char quote);
    Token scanTemplate();
    Token scanIdentifierOrKeyword();
    Token scanRegex(int tline, int tcol);   // only when context says so
    Token scanPunctuation();

    // ---- JSX token scanners ----
    Token scanJSXText();      // raw text between > ... <
    Token scanJSXString();    // attribute "..." or '...' value

    // ---- helpers ----
    static TokenKind keywordKind(const std::string& word);
    Token makeToken(TokenKind k, std::string v, int l, int c) const;

    // Track last significant token to disambiguate / vs regex, < vs JSXLess
    TokenKind lastKind_ = TokenKind::EndOfFile;

    // JSX child-mode flag: set by parser via friend or accessor
    // We expose a mode stack so the parser can push/pop
    std::vector<LexMode> modeStack_;
    LexMode currentMode() const;

public:
    void pushMode(LexMode m) { modeStack_.push_back(m); }
    void popMode()           { if (!modeStack_.empty()) modeStack_.pop_back(); }
};

