// ---------------------------------------------------------------------------
// Lex mode stack — controls whether < is JS or JSX
// ---------------------------------------------------------------------------
enum class LexMode {
    JS,           // normal JS tokenisation
    JSXTag,       // inside <Tag ... >
    JSXChildren,  // between > and </
};

class Lexer {
public:
    explicit Lexer(std::string source);

    // Produce all tokens eagerly; parser works from the resulting vector.
    std::vector<Token> tokenize();

    // Parser drives the mode stack so the lexer knows JSX context.
    void pushMode(LexMode m) { modeStack_.push_back(m); }
    void popMode()           { if (!modeStack_.empty()) modeStack_.pop_back(); }

private:
    std::string            src_;
    size_t                 pos_      = 0;
    int                    line_     = 1;
    int                    col_      = 1;
    TokenKind              lastKind_ = TokenKind::EndOfFile;
    std::vector<LexMode>   modeStack_;

    LexMode currentMode() const;

    // --- character helpers ---
    char   peek(int offset = 0) const;
    char   advance();
    bool   atEnd() const;
    void   skipWhitespaceAndComments();

    // --- JS scanners ---
    Token scanNumber();
    Token scanString(char quote);
    Token scanTemplate();
    Token scanIdentifierOrKeyword();
    Token scanRegex(int tline, int tcol);
    Token scanPunctuation();

    // --- JSX scanners ---
    Token scanJSXText();
    Token scanJSXString(char quote);

    // --- helpers ---
    static TokenKind keywordKind(const std::string& w);
    Token makeToken(TokenKind k, std::string v, int l, int c) const;

    // True when a / should start a regex rather than divide
    bool regexAllowed() const;
    // True when a < should be treated as JSX opener
    bool jsxAllowed() const;
};

