// ---------------------------------------------------------------------------
// Forward declarations
// ---------------------------------------------------------------------------
struct Node;
using NodePtr  = std::unique_ptr<Node>;
using NodeList = std::vector<NodePtr>;

// ---------------------------------------------------------------------------
// Node kinds
// ---------------------------------------------------------------------------
enum class NodeKind {
    // --- Statements ---
    Program,
    ImportDecl,
    ExportDefaultDecl,
    ExportNamedDecl,
    FunctionDecl,
    ArrowFunctionExpr,
    BlockStmt,
    ReturnStmt,
    ExprStmt,
    IfStmt,
    ForStmt,
    WhileStmt,
    VarDecl,        // const/let/var x = ...
    VarDeclarator,

    // --- Expressions ---
    Identifier,
    NumericLiteral,
    StringLiteral,
    TemplateLiteral,
    BoolLiteral,
    NullLiteral,
    BinaryExpr,
    UnaryExpr,
    LogicalExpr,
    AssignExpr,
    CallExpr,
    MemberExpr,
    NewExpr,
    ConditionalExpr,
    SpreadElement,
    ArrayExpr,
    ObjectExpr,
    ObjectProperty,
    SequenceExpr,

    // --- JSX ---
    JSXElement,
    JSXFragment,
    JSXOpeningElement,
    JSXClosingElement,
    JSXSelfClosingElement,
    JSXAttribute,
    JSXSpreadAttribute,
    JSXExpressionContainer,
    JSXText,
    JSXIdentifier,
    JSXMemberExpr,   // Foo.Bar in <Foo.Bar />
};

// ---------------------------------------------------------------------------
// Base node — all concrete data hangs off Node via the 'as' union/variant
// ---------------------------------------------------------------------------
struct Node {
    NodeKind kind;
    int      line = 0;
    int      col  = 0;

    // Children / payload — kept flat to avoid deep inheritance hierarchies.
    // Named fields used by code-gen; unused fields are default-initialised.

    std::string        name;          // identifiers, tag names, operators
    std::string        value;         // literals
    bool               boolVal = false;

    NodeList           children;      // generic child list
    NodeList           params;        // function params
    NodeList           body;          // block body
    NodePtr            init;          // var declarator init / for-init
    NodePtr            test;          // if/for/while condition
    NodePtr            update;        // for-update
    NodePtr            consequent;
    NodePtr            alternate;
    NodePtr            callee;        // CallExpr
    NodeList           arguments;     // CallExpr args
    NodePtr            object;        // MemberExpr object / JSXMemberExpr
    NodePtr            property;      // MemberExpr property
    bool               computed = false;
    NodeList           declarations;  // VarDecl
    NodePtr            declaration;   // ExportDefaultDecl
    NodeList           specifiers;    // ImportDecl named imports
    std::string        source;        // ImportDecl module path
    NodeList           attributes;    // JSXElement attributes
    NodePtr            openingElement;
    NodePtr            closingElement;
    bool               selfClosing = false;
    NodePtr            expression;    // JSXExpressionContainer / ExprStmt
    std::string        varKind;       // "const" | "let" | "var"
    bool               async_ = false;
    NodeList           quasis;        // TemplateLiteral cooked strings
    NodeList           exprs;         // TemplateLiteral expressions
};

// ---------------------------------------------------------------------------
// Factory helpers
// ---------------------------------------------------------------------------
inline NodePtr makeNode(NodeKind k, int line = 0, int col = 0) {
    auto n   = std::make_unique<Node>();
    n->kind  = k;
    n->line  = line;
    n->col   = col;
    return n;
}

