// ---------------------------------------------------------------------------
// ParseError — carries line/col for user-facing diagnostics
// ---------------------------------------------------------------------------
struct ParseError : std::runtime_error {
    int line, col;
    ParseError(const std::string& msg, int l, int c)
        : std::runtime_error(msg), line(l), col(c) {}
};

// ---------------------------------------------------------------------------
// Parser — recursive-descent, JS grammar with JSX branches
// ---------------------------------------------------------------------------
class Parser {
public:
    // Takes ownership of the token stream produced by Lexer::tokenize().
    explicit Parser(std::vector<Token> tokens);

    // Entry point: returns a Program node.
    NodePtr parse();

private:
    std::vector<Token> tokens_;
    size_t             pos_ = 0;

    // --- token stream helpers ---
    const Token& peek(int offset = 0) const;
    const Token& advance();
    bool         check(TokenKind k) const;
    bool         match(TokenKind k);
    const Token& expect(TokenKind k, const std::string& msg);
    bool         atEnd() const;
    void         error(const std::string& msg) const;

    // --- statement parsers ---
    NodePtr parseStatement();
    NodePtr parseImportDecl();
    NodePtr parseExportDecl();
    NodePtr parseFunctionDecl(bool async_ = false);
    NodePtr parseBlockStmt();
    NodePtr parseReturnStmt();
    NodePtr parseIfStmt();
    NodePtr parseForStmt();
    NodePtr parseWhileStmt();
    NodePtr parseVarDecl();
    NodePtr parseExprStmt();

    // --- expression parsers (precedence climbing) ---
    NodePtr parseExpr();
    NodePtr parseAssignExpr();
    NodePtr parseConditionalExpr();
    NodePtr parseLogicalOrExpr();
    NodePtr parseLogicalAndExpr();
    NodePtr parseBitwiseOrExpr();
    NodePtr parseBitwiseXorExpr();
    NodePtr parseBitwiseAndExpr();
    NodePtr parseEqualityExpr();
    NodePtr parseRelationalExpr();
    NodePtr parseShiftExpr();
    NodePtr parseAdditiveExpr();
    NodePtr parseMultiplicativeExpr();
    NodePtr parseUnaryExpr();
    NodePtr parseUpdateExpr();
    NodePtr parseCallMemberExpr();
    NodePtr parsePrimaryExpr();

    // --- literals / special primaries ---
    NodePtr parseArrowFunction(NodePtr firstParam);
    NodePtr parseFunctionExpr(bool async_);
    NodePtr parseArrayExpr();
    NodePtr parseObjectExpr();
    NodePtr parseTemplateLiteral();

    // --- JSX parsers ---
    // Returns a JSXElement or JSXFragment node.
    NodePtr parseJSXElement();
    NodePtr parseJSXFragment();
    NodePtr parseJSXOpeningElement();       // <Tag attrs>
    NodePtr parseJSXSelfClosingElement();   // <Tag attrs />
    NodePtr parseJSXClosingElement();       // </Tag>
    NodePtr parseJSXAttribute();            // single attr or {...spread}
    NodeList parseJSXChildren();            // text / {expr} / nested elements
    NodePtr parseJSXExprContainer();        // { expr }

    std::string parseJSXTagName();          // identifier or Foo.Bar

    // True when the current < should open JSX (not a relational op)
    bool inExpressionContext_ = false;

    // Helper: wrap a params list for arrow function detection
    bool looksLikeArrowParams() const;
};

