    // statements
    void genImportDecl(const Node& n);
    void genExportDefaultDecl(const Node& n);
    void genExportNamedDecl(const Node& n);
    void genFunctionDecl(const Node& n);
    void genBlockStmt(const Node& n);
    void genReturnStmt(const Node& n);
