#pragma once
#include <string>
#include <stdexcept>

// ---------------------------------------------------------------------------
// Shared error types used across lexer, parser, and codegen
// ---------------------------------------------------------------------------

struct LexError : std::runtime_error {
    int line, col;
    LexError(const std::string& msg, int l, int c)
        : std::runtime_error(msg), line(l), col(c) {}
};

struct ParseError : std::runtime_error {
    int line, col;
    ParseError(const std::string& msg, int l, int c)
        : std::runtime_error(msg), line(l), col(c) {}
};

struct CodeGenError : std::runtime_error {
    explicit CodeGenError(const std::string& msg)
        : std::runtime_error(msg) {}
};

// Format a human-readable diagnostic line: "error at line L, col C: msg"
inline std::string formatDiag(const std::string& kind,
                               const std::string& msg,
                               int line, int col) {
    return kind + " at line " + std::to_string(line)
         + ", col "  + std::to_string(col)
         + ": "      + msg;
}

#include "lexer.h"
#include "diagnostics.h"
#include <cctype>
#include <stdexcept>
#include <unordered_map>

// ---------------------------------------------------------------------------
// Construction
// ---------------------------------------------------------------------------
Lexer::Lexer(std::string source) : src_(std::move(source)) {
    modeStack_.push_back(LexMode::JS);
}

// ---------------------------------------------------------------------------
// Mode stack
// ---------------------------------------------------------------------------
LexMode Lexer::currentMode() const {
    return modeStack_.empty() ? LexMode::JS : modeStack_.back();
}

void Lexer::pushMode(LexMode m) { modeStack_.push_back(m); }
void Lexer::popMode()           { if (!modeStack_.empty()) modeStack_.pop_back(); }

// ---------------------------------------------------------------------------
// Character helpers
// ---------------------------------------------------------------------------
bool Lexer::atEnd() const { return pos_ >= src_.size(); }

char Lexer::peek(int offset) const {
    size_t i = pos_ + offset;
    return i < src_.size() ? src_[i] : '\0';
}

char Lexer::advance() {
    char c = src_[pos_++];
    if (c == '\n') { ++line_; col_ = 1; }
    else            { ++col_; }
    return c;
}

void Lexer::skipWhitespaceAndComments() {
    while (!atEnd()) {
        char c = peek();
        if (std::isspace(static_cast<unsigned char>(c))) {
            advance();
        } else if (c == '/' && peek(1) == '/') {
            while (!atEnd() && peek() != '\n') advance();
        } else if (c == '/' && peek(1) == '*') {
            advance(); advance(); // consume /*
            while (!atEnd() && !(peek() == '*' && peek(1) == '/'))
                advance();
            if (!atEnd()) { advance(); advance(); } // consume */
        } else {
            break;
        }
    }
}

Token Lexer::makeToken(TokenKind k, std::string v, int l, int c) const {
    return Token{k, std::move(v), l, c};
}

// ---------------------------------------------------------------------------
// Keyword table
// ---------------------------------------------------------------------------
TokenKind Lexer::keywordKind(const std::string& w) {
    static const std::unordered_map<std::string, TokenKind> kw = {
        {"return",     TokenKind::KW_return},
        {"import",     TokenKind::KW_import},
        {"export",     TokenKind::KW_export},
        {"default",    TokenKind::KW_default},
        {"function",   TokenKind::KW_function},
        {"const",      TokenKind::KW_const},
        {"let",        TokenKind::KW_let},
        {"var",        TokenKind::KW_var},
        {"from",       TokenKind::KW_from},
        {"as",         TokenKind::KW_as},
        {"if",         TokenKind::KW_if},
        {"else",       TokenKind::KW_else},
        {"for",        TokenKind::KW_for},
        {"while",      TokenKind::KW_while},
        {"do",         TokenKind::KW_do},
        {"new",        TokenKind::KW_new},
        {"typeof",     TokenKind::KW_typeof},
        {"void",       TokenKind::KW_void},
        {"delete",     TokenKind::KW_delete},
        {"in",         TokenKind::KW_in},
        {"instanceof", TokenKind::KW_instanceof},
        {"class",      TokenKind::KW_class},
        {"extends",    TokenKind::KW_extends},
        {"this",       TokenKind::KW_this},
        {"super",      TokenKind::KW_super},
        {"null",       TokenKind::KW_null},
        {"true",       TokenKind::KW_true},
        {"false",      TokenKind::KW_false},
        {"async",      TokenKind::KW_async},
        {"await",      TokenKind::KW_await},
    };
    auto it = kw.find(w);
    return it != kw.end() ? it->second : TokenKind::Identifier;
}

// ---------------------------------------------------------------------------
// JS scanners
// ---------------------------------------------------------------------------
Token Lexer::scanNumber() {
    int l = line_, c = col_;
    std::string v;
    // hex
    if (peek() == '0' && (peek(1) == 'x' || peek(1) == 'X')) {
        v += advance(); v += advance();
        while (!atEnd() && std::isxdigit(static_cast<unsigned char>(peek())))
            v += advance();
        return makeToken(TokenKind::Number, v, l, c);
    }
    while (!atEnd() && std::isdigit(static_cast<unsigned char>(peek())))
        v += advance();
    if (!atEnd() && peek() == '.' && std::isdigit(static_cast<unsigned char>(peek(1)))) {
        v += advance();
        while (!atEnd() && std::isdigit(static_cast<unsigned char>(peek())))
            v += advance();
    }
    if (!atEnd() && (peek() == 'e' || peek() == 'E')) {
        v += advance();
        if (!atEnd() && (peek() == '+' || peek() == '-')) v += advance();
        while (!atEnd() && std::isdigit(static_cast<unsigned char>(peek())))
            v += advance();
    }
    return makeToken(TokenKind::Number, v, l, c);
}

Token Lexer::scanString(char quote) {
    int l = line_, c = col_;
    advance(); // opening quote
    std::string v;
    while (!atEnd() && peek() != quote) {
        if (peek() == '\\') { v += advance(); if (!atEnd()) v += advance(); }
        else                   v += advance();
    }
    if (atEnd()) throw LexError("Unterminated string literal", l, c);
    advance(); // closing quote
    return makeToken(TokenKind::String, v, l, c);
}

Token Lexer::scanTemplate() {
    int l = line_, c = col_;
    advance(); // `
    std::string v;
    int depth = 0;
    while (!atEnd()) {
        char ch = peek();
        if (ch == '\\') { v += advance(); if (!atEnd()) v += advance(); }
        else if (ch == '$' && peek(1) == '{') {
            v += advance(); v += advance(); ++depth;
        } else if (ch == '}' && depth > 0) {
            v += advance(); --depth;
        } else if (ch == '`' && depth == 0) {
            advance(); break;
        } else {
            v += advance();
        }
    }
    return makeToken(TokenKind::TemplateString, v, l, c);
}

Token Lexer::scanIdentifierOrKeyword() {
    int l = line_, c = col_;
    std::string v;
    while (!atEnd() && (std::isalnum(static_cast<unsigned char>(peek()))
                        || peek() == '_' || peek() == '$'))
        v += advance();
    TokenKind k = keywordKind(v);
    return makeToken(k, v, l, c);
}

Token Lexer::scanRegex(int tline, int tcol) {
    std::string v = "/";
    bool inClass = false;
    while (!atEnd()) {
        char ch = peek();
        if (ch == '\\') { v += advance(); if (!atEnd()) v += advance(); continue; }
        if (ch == '[')  { inClass = true;  v += advance(); continue; }
        if (ch == ']')  { inClass = false; v += advance(); continue; }
        if (ch == '/' && !inClass) { v += advance(); break; }
        v += advance();
    }
    // flags
    while (!atEnd() && std::isalpha(static_cast<unsigned char>(peek())))
        v += advance();
    return makeToken(TokenKind::Regex, v, tline, tcol);
}

// ---------------------------------------------------------------------------
// Disambiguation helpers
// ---------------------------------------------------------------------------
bool Lexer::regexAllowed() const {
    switch (lastKind_) {
        case TokenKind::RParen:
        case TokenKind::RBracket:
        case TokenKind::Identifier:
        case TokenKind::Number:
        case TokenKind::String:
        case TokenKind::TemplateString:
        case TokenKind::PlusPlus:
        case TokenKind::MinusMinus:
            return false;
        default:
            return true;
    }
}

// < starts JSX only after: return, (, =, ,, [, {, ternary :, ||, &&, arrow =>
bool Lexer::jsxAllowed() const {
    switch (lastKind_) {
        case TokenKind::KW_return:
        case TokenKind::LParen:
        case TokenKind::Equals:
        case TokenKind::Comma:
        case TokenKind::LBracket:
        case TokenKind::LBrace:
        case TokenKind::Colon:
        case TokenKind::PipePipe:
        case TokenKind::AmpAmp:
        case TokenKind::Arrow:
        case TokenKind::QuestionQuestion:
        case TokenKind::EndOfFile:
            return true;
        default:
            return false;
    }
}

// ---------------------------------------------------------------------------
// JSX scanners
// ---------------------------------------------------------------------------
Token Lexer::scanJSXText() {
    int l = line_, c = col_;
    std::string v;
    while (!atEnd() && peek() != '<' && peek() != '{')
        v += advance();
    return makeToken(TokenKind::JSXText, v, l, c);
}

Token Lexer::scanJSXString(char quote) {
    int l = line_, c = col_;
    advance(); // opening quote
    std::string v;
    while (!atEnd() && peek() != quote) {
        if (peek() == '\\') { v += advance(); if (!atEnd()) v += advance(); }
        else                   v += advance();
    }
    if (atEnd()) throw LexError("Unterminated JSX attribute string", l, c);
    advance();
    return makeToken(TokenKind::JSXString, v, l, c);
}

// ---------------------------------------------------------------------------
// Punctuation scanner (JS mode)
// ---------------------------------------------------------------------------
Token Lexer::scanPunctuation() {
    int l = line_, c = col_;
    char ch = advance();

    auto make = [&](TokenKind k, std::string v) {
        return makeToken(k, std::move(v), l, c);
    };

    switch (ch) {
        case '(': return make(TokenKind::LParen,     "(");
        case ')': return make(TokenKind::RParen,     ")");
        case '{': return make(TokenKind::LBrace,     "{");
        case '}': return make(TokenKind::RBrace,     "}");
        case '[': return make(TokenKind::LBracket,   "[");
        case ']': return make(TokenKind::RBracket,   "]");
        case ';': return make(TokenKind::Semicolon,  ";");
        case ':': return make(TokenKind::Colon,      ":");
        case ',': return make(TokenKind::Comma,      ",");
        case '~': return make(TokenKind::Tilde,      "~");
        case '^': return make(TokenKind::Caret,      "^");
        case '%': {
            if (peek() == '=') { advance(); return make(TokenKind::PercentEquals, "%="); }
            return make(TokenKind::Percent, "%");
        }
        case '?': {
            if (peek() == '?') { advance(); return make(TokenKind::QuestionQuestion, "??"); }
            return make(TokenKind::QuestionMark, "?");
        }
        case '.': {
            if (peek() == '.' && peek(1) == '.') {
                advance(); advance(); return make(TokenKind::DotDotDot, "...");
            }
            return make(TokenKind::Dot, ".");
        }
        case '=': {
            if (peek() == '>') { advance(); return make(TokenKind::Arrow, "=>"); }
            if (peek() == '=') {
                advance();
                if (peek() == '=') { advance(); return make(TokenKind::EqualsEqualsEquals, "==="); }
                return make(TokenKind::EqualsEquals, "==");
            }
            return make(TokenKind::Equals, "=");
        }
        case '!': {
            if (peek() == '=') {
                advance();
                if (peek() == '=') { advance(); return make(TokenKind::BangEqualsEquals, "!=="); }
                return make(TokenKind::BangEquals, "!=");
            }
            return make(TokenKind::Bang, "!");
        }
        case '<': {
            if (jsxAllowed()) return make(TokenKind::JSXLess, "<");
            if (peek() == '<') { advance(); return make(TokenKind::LShift, "<<"); }
            if (peek() == '=') { advance(); return make(TokenKind::LessEquals, "<="); }
            return make(TokenKind::Less, "<");
        }
        case '>': {
            if (peek() == '>') {
                advance();
                if (peek() == '>') { advance(); return make(TokenKind::URShift, ">>>"); }
                return make(TokenKind::RShift, ">>");
            }
            if (peek() == '=') { advance(); return make(TokenKind::GreaterEquals, ">="); }
            return make(TokenKind::Greater, ">");
        }
        case '+': {
            if (peek() == '+') { advance(); return make(TokenKind::PlusPlus, "++"); }
            if (peek() == '=') { advance(); return make(TokenKind::PlusEquals, "+="); }
            return make(TokenKind::Plus, "+");
        }
        case '-': {
            if (peek() == '-') { advance(); return make(TokenKind::MinusMinus, "--"); }
            if (peek() == '=') { advance(); return make(TokenKind::MinusEquals, "-="); }
            return make(TokenKind::Minus, "-");
        }
        case '*': {
            if (peek() == '=') { advance(); return make(TokenKind::StarEquals, "*="); }
            return make(TokenKind::Star, "*");
        }
        case '/': {
            if (regexAllowed()) return scanRegex(l, c);
            if (peek() == '=') { advance(); return make(TokenKind::SlashEquals, "/="); }
            return make(TokenKind::Slash, "/");
        }
        case '&': {
            if (peek() == '&') { advance(); return make(TokenKind::AmpAmp, "&&"); }
            return make(TokenKind::Amp, "&");
        }
        case '|': {
            if (peek() == '|') { advance(); return make(TokenKind::PipePipe, "||"); }
            return make(TokenKind::Pipe, "|");
        }
        default:
            return make(TokenKind::Unknown, std::string(1, ch));
    }
}

// ---------------------------------------------------------------------------
// Main tokenise loop
// ---------------------------------------------------------------------------
std::vector<Token> Lexer::tokenize() {
    std::vector<Token> tokens;

    while (true) {
        skipWhitespaceAndComments();
        if (atEnd()) {
            tokens.push_back(makeToken(TokenKind::EndOfFile, "", line_, col_));
            break;
        }

        LexMode mode = currentMode();
        Token   tok;

        if (mode == LexMode::JSXChildren) {
            char ch = peek();
            if (ch == '<') {
                int l = line_, c = col_;
                advance();
                if (peek() == '/') {
                    advance();
                    tok = makeToken(TokenKind::JSXLessSlash, "</", l, c);
                } else {
                    tok = makeToken(TokenKind::JSXLess, "<", l, c);
                }
            } else if (ch == '{') {
                int l = line_, c = col_;
                advance();
                tok = makeToken(TokenKind::LBrace, "{", l, c);
                // Parser will pop JSXChildren and push JS for the expression,
                // then push JSXChildren again after }.
            } else {
                tok = scanJSXText();
            }
        } else if (mode == LexMode::JSXTag) {
            char ch = peek();
            if (ch == '/' && peek(1) == '>') {
                int l = line_, c = col_;
                advance(); advance();
                tok = makeToken(TokenKind::JSXSlashGreater, "/>", l, c);
            } else if (ch == '>') {
                int l = line_, c = col_;
                advance();
                tok = makeToken(TokenKind::JSXGreater, ">", l, c);
            } else if (ch == '{') {
                int l = line_, c = col_;
                advance();
                tok = makeToken(TokenKind::LBrace, "{", l, c);
            } else if (ch == '"' || ch == '\'') {
                tok = scanJSXString(ch);
            } else if (std::isalpha(static_cast<unsigned char>(ch)) || ch == '_') {
                tok = scanIdentifierOrKeyword();
                tok.kind = TokenKind::Identifier; // tag/attr names aren't keywords in JSX
            } else if (ch == '.') {
                int l = line_, c = col_;
                advance();
                tok = makeToken(TokenKind::Dot, ".", l, c);
            } else if (ch == '=') {
                int l = line_, c = col_;
                advance();
                tok = makeToken(TokenKind::Equals, "=", l, c);
            } else if (ch == '.') {
                int l = line_, c = col_;
                advance();
                tok = makeToken(TokenKind::Dot, ".", l, c);
            } else if (ch == '.' && peek(1) == '.' && peek(2) == '.') {
                int l = line_, c = col_;
                advance(); advance(); advance();
                tok = makeToken(TokenKind::DotDotDot, "...", l, c);
            } else {
                // Fallback: identifiers, dots, equals already handled above.
                tok = makeToken(TokenKind::Unknown, std::string(1, advance()), line_, col_);
            }
        } else {
            // Normal JS mode
            char ch = peek();
            if (std::isdigit(static_cast<unsigned char>(ch))) {
                tok = scanNumber();
            } else if (ch == '"' || ch == '\'') {
                tok = scanString(ch);
            } else if (ch == '`') {
                tok = scanTemplate();
            } else if (std::isalpha(static_cast<unsigned char>(ch)) || ch == '_' || ch == '$') {
                tok = scanIdentifierOrKeyword();
            } else {
                tok = scanPunctuation();
            }
        }

        lastKind_ = tok.kind;
        tokens.push_back(std::move(tok));
    }

    return tokens;
}

#include "parser.h"
#include "diagnostics.h"
#include <cassert>
#include <sstream>

// ---------------------------------------------------------------------------
// Construction
// ---------------------------------------------------------------------------
Parser::Parser(std::vector<Token> tokens) : tokens_(std::move(tokens)) {}

// ---------------------------------------------------------------------------
// Token stream helpers
// ---------------------------------------------------------------------------
const Token& Parser::peek(int offset) const {
    size_t i = pos_ + offset;
    if (i >= tokens_.size()) return tokens_.back(); // EOF sentinel
    return tokens_[i];
}

const Token& Parser::advance() {
    if (!atEnd()) ++pos_;
    return tokens_[pos_ - 1];
}

bool Parser::check(TokenKind k) const { return peek().kind == k; }

bool Parser::match(TokenKind k) {
    if (check(k)) { advance(); return true; }
    return false;
}

const Token& Parser::expect(TokenKind k, const std::string& msg) {
    if (!check(k)) {
        const Token& t = peek();
        throw ParseError("Expected " + msg + ", got '" + t.value + "'", t.line, t.col);
    }
    return advance();
}

bool Parser::atEnd() const { return peek().kind == TokenKind::EndOfFile; }

void Parser::error(const std::string& msg) const {
    const Token& t = peek();
    throw ParseError(msg, t.line, t.col);
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------
NodePtr Parser::parse() {
    auto prog = makeNode(NodeKind::Program, 1, 1);
    while (!atEnd()) {
        prog->body.push_back(parseStatement());
    }
    return prog;
}

// ---------------------------------------------------------------------------
// Statements
// ---------------------------------------------------------------------------
NodePtr Parser::parseStatement() {
    const Token& t = peek();

    switch (t.kind) {
        case TokenKind::KW_import:   return parseImportDecl();
        case TokenKind::KW_export:   return parseExportDecl();
        case TokenKind::KW_function: return parseFunctionDecl();
        case TokenKind::KW_async:
            if (peek(1).kind == TokenKind::KW_function) {
                advance(); // consume async
                return parseFunctionDecl(true);
            }
            return parseExprStmt();
        case TokenKind::KW_const:
        case TokenKind::KW_let:
        case TokenKind::KW_var:      return parseVarDecl();
        case TokenKind::LBrace:      return parseBlockStmt();
        case TokenKind::KW_return:   return parseReturnStmt();
        case TokenKind::KW_if:       return parseIfStmt();
        case TokenKind::KW_for:      return parseForStmt();
        case TokenKind::KW_while:    return parseWhileStmt();
        default:                     return parseExprStmt();
    }
}

NodePtr Parser::parseImportDecl() {
    const Token& start = expect(TokenKind::KW_import, "import");
    auto n = makeNode(NodeKind::ImportDecl, start.line, start.col);

    if (check(TokenKind::String)) {
        // import "side-effect"
        n->source = advance().value;
    } else if (check(TokenKind::LBrace)) {
        // import { X, Y } from "mod"
        advance();
        while (!check(TokenKind::RBrace) && !atEnd()) {
            auto spec = makeNode(NodeKind::Identifier, peek().line, peek().col);
            spec->name = advance().value;
            if (match(TokenKind::KW_as)) {
                spec->value = advance().value; // local alias
            }
            n->specifiers.push_back(std::move(spec));
            if (!match(TokenKind::Comma)) break;
        }
        expect(TokenKind::RBrace, "}");
        expect(TokenKind::KW_from, "from");
        n->source = expect(TokenKind::String, "module path").value;
    } else if (check(TokenKind::Star)) {
        // import * as ns from "mod"
        advance();
        expect(TokenKind::KW_as, "as");
        auto spec = makeNode(NodeKind::Identifier, peek().line, peek().col);
        spec->name  = "*";
        spec->value = advance().value;
        n->specifiers.push_back(std::move(spec));
        expect(TokenKind::KW_from, "from");
        n->source = expect(TokenKind::String, "module path").value;
    } else {
        // import Default from "mod"
        auto spec = makeNode(NodeKind::Identifier, peek().line, peek().col);
        spec->name = advance().value;
        n->specifiers.push_back(std::move(spec));
        if (match(TokenKind::Comma)) {
            // import Default, { Named } from "mod"
            expect(TokenKind::LBrace, "{");
            while (!check(TokenKind::RBrace) && !atEnd()) {
                auto s = makeNode(NodeKind::Identifier, peek().line, peek().col);
                s->name = advance().value;
                n->specifiers.push_back(std::move(s));
                if (!match(TokenKind::Comma)) break;
            }
            expect(TokenKind::RBrace, "}");
        }
        expect(TokenKind::KW_from, "from");
        n->source = expect(TokenKind::String, "module path").value;
    }
    match(TokenKind::Semicolon);
    return n;
}

NodePtr Parser::parseExportDecl() {
    const Token& start = expect(TokenKind::KW_export, "export");

    if (match(TokenKind::KW_default)) {
        auto n = makeNode(NodeKind::ExportDefaultDecl, start.line, start.col);
        if (check(TokenKind::KW_function))
            n->declaration = parseFunctionDecl();
        else
            n->declaration = parseExpr();
        match(TokenKind::Semicolon);
        return n;
    }

    auto n = makeNode(NodeKind::ExportNamedDecl, start.line, start.col);
    if (check(TokenKind::KW_function)) {
        n->declaration = parseFunctionDecl();
    } else if (check(TokenKind::KW_const) || check(TokenKind::KW_let) || check(TokenKind::KW_var)) {
        n->declaration = parseVarDecl();
    } else {
        n->declaration = parseExprStmt();
    }
    return n;
}

NodePtr Parser::parseFunctionDecl(bool isAsync) {
    const Token& start = expect(TokenKind::KW_function, "function");
    auto n = makeNode(NodeKind::FunctionDecl, start.line, start.col);
    n->async_ = isAsync;
    if (check(TokenKind::Identifier)) n->name = advance().value;
    expect(TokenKind::LParen, "(");
    while (!check(TokenKind::RParen) && !atEnd()) {
        auto p = makeNode(NodeKind::Identifier, peek().line, peek().col);
        if (match(TokenKind::DotDotDot)) p->name = "...";
        p->name += expect(TokenKind::Identifier, "parameter name").value;
        n->params.push_back(std::move(p));
        if (!match(TokenKind::Comma)) break;
    }
    expect(TokenKind::RParen, ")");
    n->body.push_back(parseBlockStmt());
    return n;
}

NodePtr Parser::parseBlockStmt() {
    const Token& start = expect(TokenKind::LBrace, "{");
    auto n = makeNode(NodeKind::BlockStmt, start.line, start.col);
    while (!check(TokenKind::RBrace) && !atEnd())
        n->body.push_back(parseStatement());
    expect(TokenKind::RBrace, "}");
    return n;
}

NodePtr Parser::parseReturnStmt() {
    const Token& start = expect(TokenKind::KW_return, "return");
    auto n = makeNode(NodeKind::ReturnStmt, start.line, start.col);
    if (!check(TokenKind::Semicolon) && !check(TokenKind::RBrace) && !atEnd()) {
        inExpressionContext_ = true;
        n->expression = parseExpr();
        inExpressionContext_ = false;
    }
    match(TokenKind::Semicolon);
    return n;
}

NodePtr Parser::parseIfStmt() {
    const Token& start = expect(TokenKind::KW_if, "if");
    auto n = makeNode(NodeKind::IfStmt, start.line, start.col);
    expect(TokenKind::LParen, "(");
    n->test = parseExpr();
    expect(TokenKind::RParen, ")");
    n->consequent = parseStatement();
    if (match(TokenKind::KW_else)) n->alternate = parseStatement();
    return n;
}

NodePtr Parser::parseForStmt() {
    const Token& start = expect(TokenKind::KW_for, "for");
    auto n = makeNode(NodeKind::ForStmt, start.line, start.col);
    expect(TokenKind::LParen, "(");
    if (!check(TokenKind::Semicolon))
        n->init = (check(TokenKind::KW_const) || check(TokenKind::KW_let) || check(TokenKind::KW_var))
                  ? parseVarDecl() : parseExprStmt();
    else match(TokenKind::Semicolon);
    if (!check(TokenKind::Semicolon)) n->test = parseExpr();
    expect(TokenKind::Semicolon, ";");
    if (!check(TokenKind::RParen))    n->update = parseExpr();
    expect(TokenKind::RParen, ")");
    n->body.push_back(parseStatement());
    return n;
}

NodePtr Parser::parseWhileStmt() {
    const Token& start = expect(TokenKind::KW_while, "while");
    auto n = makeNode(NodeKind::WhileStmt, start.line, start.col);
    expect(TokenKind::LParen, "(");
    n->test = parseExpr();
    expect(TokenKind::RParen, ")");
    n->body.push_back(parseStatement());
    return n;
}

NodePtr Parser::parseVarDecl() {
    const Token& start = peek();
    auto n = makeNode(NodeKind::VarDecl, start.line, start.col);
    n->varKind = advance().value; // const/let/var
    do {
        auto decl = makeNode(NodeKind::VarDeclarator, peek().line, peek().col);
        decl->name = expect(TokenKind::Identifier, "variable name").value;
        if (match(TokenKind::Equals)) {
            inExpressionContext_ = true;
            decl->init = parseAssignExpr();
            inExpressionContext_ = false;
        }
        n->declarations.push_back(std::move(decl));
    } while (match(TokenKind::Comma));
    match(TokenKind::Semicolon);
    return n;
}

NodePtr Parser::parseExprStmt() {
    const Token& start = peek();
    auto n = makeNode(NodeKind::ExprStmt, start.line, start.col);
    n->expression = parseExpr();
    match(TokenKind::Semicolon);
    return n;
}

// ---------------------------------------------------------------------------
// Expression parsers (precedence climbing)
// ---------------------------------------------------------------------------
NodePtr Parser::parseExpr() {
    auto left = parseAssignExpr();
    if (check(TokenKind::Comma)) {
        auto seq = makeNode(NodeKind::SequenceExpr, left->line, left->col);
        seq->children.push_back(std::move(left));
        while (match(TokenKind::Comma))
            seq->children.push_back(parseAssignExpr());
        return seq;
    }
    return left;
}

NodePtr Parser::parseAssignExpr() {
    auto left = parseConditionalExpr();

    TokenKind k = peek().kind;
    if (k == TokenKind::Equals       || k == TokenKind::PlusEquals  ||
        k == TokenKind::MinusEquals  || k == TokenKind::StarEquals   ||
        k == TokenKind::SlashEquals  || k == TokenKind::PercentEquals) {
        std::string op = advance().value;
        auto n = makeNode(NodeKind::AssignExpr, left->line, left->col);
        n->name  = op;
        n->object   = std::move(left);
        n->property = parseAssignExpr();
        return n;
    }
    return left;
}

NodePtr Parser::parseConditionalExpr() {
    auto cond = parseLogicalOrExpr();
    if (match(TokenKind::QuestionMark)) {
        auto n = makeNode(NodeKind::ConditionalExpr, cond->line, cond->col);
        n->test       = std::move(cond);
        n->consequent = parseAssignExpr();
        expect(TokenKind::Colon, ":");
        n->alternate  = parseAssignExpr();
        return n;
    }
    return cond;
}

static NodePtr makeBinary(NodeKind kind, NodePtr left, std::string op, NodePtr right) {
    auto n = makeNode(kind, left->line, left->col);
    n->name     = op;
    n->object   = std::move(left);
    n->property = std::move(right);
    return n;
}

NodePtr Parser::parseLogicalOrExpr() {
    auto left = parseLogicalAndExpr();
    while (check(TokenKind::PipePipe) || check(TokenKind::QuestionQuestion)) {
        std::string op = advance().value;
        left = makeBinary(NodeKind::LogicalExpr, std::move(left), op, parseLogicalAndExpr());
    }
    return left;
}

NodePtr Parser::parseLogicalAndExpr() {
    auto left = parseBitwiseOrExpr();
    while (check(TokenKind::AmpAmp)) {
        std::string op = advance().value;
        left = makeBinary(NodeKind::LogicalExpr, std::move(left), op, parseBitwiseOrExpr());
    }
    return left;
}

NodePtr Parser::parseBitwiseOrExpr() {
    auto left = parseBitwiseXorExpr();
    while (check(TokenKind::Pipe)) {
        std::string op = advance().value;
        left = makeBinary(NodeKind::BinaryExpr, std::move(left), op, parseBitwiseXorExpr());
    }
    return left;
}

NodePtr Parser::parseBitwiseXorExpr() {
    auto left = parseBitwiseAndExpr();
    while (check(TokenKind::Caret)) {
        std::string op = advance().value;
        left = makeBinary(NodeKind::BinaryExpr, std::move(left), op, parseBitwiseAndExpr());
    }
    return left;
}

NodePtr Parser::parseBitwiseAndExpr() {
    auto left = parseEqualityExpr();
    while (check(TokenKind::Amp)) {
        std::string op = advance().value;
        left = makeBinary(NodeKind::BinaryExpr, std::move(left), op, parseEqualityExpr());
    }
    return left;
}

NodePtr Parser::parseEqualityExpr() {
    auto left = parseRelationalExpr();
    while (check(TokenKind::EqualsEquals)        || check(TokenKind::BangEquals) ||
           check(TokenKind::EqualsEqualsEquals)  || check(TokenKind::BangEqualsEquals)) {
        std::string op = advance().value;
        left = makeBinary(NodeKind::BinaryExpr, std::move(left), op, parseRelationalExpr());
    }
    return left;
}

NodePtr Parser::parseRelationalExpr() {
    auto left = parseShiftExpr();
    while (check(TokenKind::Less)         || check(TokenKind::Greater) ||
           check(TokenKind::LessEquals)   || check(TokenKind::GreaterEquals) ||
           check(TokenKind::KW_in)        || check(TokenKind::KW_instanceof)) {
        std::string op = advance().value;
        left = makeBinary(NodeKind::BinaryExpr, std::move(left), op, parseShiftExpr());
    }
    return left;
}

NodePtr Parser::parseShiftExpr() {
    auto left = parseAdditiveExpr();
    while (check(TokenKind::LShift) || check(TokenKind::RShift) || check(TokenKind::URShift)) {
        std::string op = advance().value;
        left = makeBinary(NodeKind::BinaryExpr, std::move(left), op, parseAdditiveExpr());
    }
    return left;
}

NodePtr Parser::parseAdditiveExpr() {
    auto left = parseMultiplicativeExpr();
    while (check(TokenKind::Plus) || check(TokenKind::Minus)) {
        std::string op = advance().value;
        left = makeBinary(NodeKind::BinaryExpr, std::move(left), op, parseMultiplicativeExpr());
    }
    return left;
}

NodePtr Parser::parseMultiplicativeExpr() {
    auto left = parseUnaryExpr();
    while (check(TokenKind::Star) || check(TokenKind::Slash) || check(TokenKind::Percent)) {
        std::string op = advance().value;
        left = makeBinary(NodeKind::BinaryExpr, std::move(left), op, parseUnaryExpr());
    }
    return left;
}

NodePtr Parser::parseUnaryExpr() {
    if (check(TokenKind::Bang)      || check(TokenKind::Minus)      ||
        check(TokenKind::Plus)      || check(TokenKind::Tilde)      ||
        check(TokenKind::KW_typeof) || check(TokenKind::KW_void)    ||
        check(TokenKind::KW_delete)) {
        const Token& op = advance();
        auto n = makeNode(NodeKind::UnaryExpr, op.line, op.col);
        n->name     = op.value;
        n->object   = parseUnaryExpr();
        return n;
    }
    return parseUpdateExpr();
}

NodePtr Parser::parseUpdateExpr() {
    if (check(TokenKind::PlusPlus) || check(TokenKind::MinusMinus)) {
        const Token& op = advance();
        auto n = makeNode(NodeKind::UnaryExpr, op.line, op.col);
        n->name   = op.value + "pre";
        n->object = parseCallMemberExpr();
        return n;
    }
    auto expr = parseCallMemberExpr();
    if (check(TokenKind::PlusPlus) || check(TokenKind::MinusMinus)) {
        const Token& op = advance();
        auto n = makeNode(NodeKind::UnaryExpr, op.line, op.col);
        n->name   = op.value + "post";
        n->object = std::move(expr);
        return n;
    }
    return expr;
}

NodePtr Parser::parseCallMemberExpr() {
    auto expr = parsePrimaryExpr();

    while (true) {
        if (match(TokenKind::LParen)) {
            // call
            auto call = makeNode(NodeKind::CallExpr, expr->line, expr->col);
            call->callee = std::move(expr);
            while (!check(TokenKind::RParen) && !atEnd()) {
                if (match(TokenKind::DotDotDot)) {
                    auto sp = makeNode(NodeKind::SpreadElement, peek().line, peek().col);
                    sp->object = parseAssignExpr();
                    call->arguments.push_back(std::move(sp));
                } else {
                    call->arguments.push_back(parseAssignExpr());
                }
                if (!match(TokenKind::Comma)) break;
            }
            expect(TokenKind::RParen, ")");
            expr = std::move(call);
        } else if (match(TokenKind::Dot)) {
            auto mem = makeNode(NodeKind::MemberExpr, expr->line, expr->col);
            mem->object   = std::move(expr);
            auto prop     = makeNode(NodeKind::Identifier, peek().line, peek().col);
            prop->name    = advance().value;
            mem->property = std::move(prop);
            mem->computed = false;
            expr = std::move(mem);
        } else if (match(TokenKind::LBracket)) {
            auto mem = makeNode(NodeKind::MemberExpr, expr->line, expr->col);
            mem->object   = std::move(expr);
            mem->property = parseExpr();
            mem->computed = true;
            expect(TokenKind::RBracket, "]");
            expr = std::move(mem);
        } else {
            break;
        }
    }
    return expr;
}

NodePtr Parser::parsePrimaryExpr() {
    const Token& t = peek();

    // JSX — triggered by JSXLess token (lexer already disambiguated)
    if (t.kind == TokenKind::JSXLess) {
        if (peek(1).kind == TokenKind::JSXGreater) // <>
            return parseJSXFragment();
        return parseJSXElement();
    }

    switch (t.kind) {
        case TokenKind::Number: {
            auto n = makeNode(NodeKind::NumericLiteral, t.line, t.col);
            n->value = advance().value;
            return n;
        }
        case TokenKind::String: {
            auto n = makeNode(NodeKind::StringLiteral, t.line, t.col);
            n->value = advance().value;
            return n;
        }
        case TokenKind::TemplateString: {
            return parseTemplateLiteral();
        }
        case TokenKind::KW_true:
        case TokenKind::KW_false: {
            auto n = makeNode(NodeKind::BoolLiteral, t.line, t.col);
            n->boolVal = (advance().kind == TokenKind::KW_true);
            return n;
        }
        case TokenKind::KW_null: {
            advance();
            return makeNode(NodeKind::NullLiteral, t.line, t.col);
        }
        case TokenKind::KW_this: {
            auto n = makeNode(NodeKind::Identifier, t.line, t.col);
            n->name = advance().value;
            return n;
        }
        case TokenKind::Identifier: {
            auto n = makeNode(NodeKind::Identifier, t.line, t.col);
            n->name = advance().value;
            // Arrow: (a) => ... or a => ...
            if (check(TokenKind::Arrow)) {
                advance(); // =>
                auto arrow = makeNode(NodeKind::ArrowFunctionExpr, n->line, n->col);
                auto param = makeNode(NodeKind::Identifier, n->line, n->col);
                param->name = n->name;
                arrow->params.push_back(std::move(param));
                if (check(TokenKind::LBrace))
                    arrow->body.push_back(parseBlockStmt());
                else {
                    inExpressionContext_ = true;
                    arrow->body.push_back(parseAssignExpr());
                    inExpressionContext_ = false;
                }
                return arrow;
            }
            return n;
        }
        case TokenKind::LParen: {
            advance(); // (
            // Could be (expr) or (params) =>
            // Minimal approach: parse expr, then check for =>
            if (check(TokenKind::RParen)) {
                // () =>
                advance();
                expect(TokenKind::Arrow, "=>");
                auto arrow = makeNode(NodeKind::ArrowFunctionExpr, t.line, t.col);
                if (check(TokenKind::LBrace))
                    arrow->body.push_back(parseBlockStmt());
                else {
                    inExpressionContext_ = true;
                    arrow->body.push_back(parseAssignExpr());
                    inExpressionContext_ = false;
                }
                return arrow;
            }
            inExpressionContext_ = true;
            auto inner = parseExpr();
            inExpressionContext_ = false;
            expect(TokenKind::RParen, ")");
            if (check(TokenKind::Arrow)) {
                // treat as arrow with single grouped param
                advance();
                auto arrow = makeNode(NodeKind::ArrowFunctionExpr, t.line, t.col);
                arrow->params.push_back(std::move(inner));
                if (check(TokenKind::LBrace))
                    arrow->body.push_back(parseBlockStmt());
                else {
                    inExpressionContext_ = true;
                    arrow->body.push_back(parseAssignExpr());
                    inExpressionContext_ = false;
                }
                return arrow;
            }
            return inner;
        }
        case TokenKind::LBracket: return parseArrayExpr();
        case TokenKind::LBrace:   return parseObjectExpr();
        case TokenKind::KW_function: return parseFunctionExpr(false);
        case TokenKind::KW_async: {
            if (peek(1).kind == TokenKind::KW_function) {
                advance();
                return parseFunctionExpr(true);
            }
            // async arrow: async (params) => body
            advance();
            auto arrow = makeNode(NodeKind::ArrowFunctionExpr, t.line, t.col);
            arrow->async_ = true;
            if (check(TokenKind::LParen)) {
                advance();
                while (!check(TokenKind::RParen) && !atEnd()) {
                    auto p = makeNode(NodeKind::Identifier, peek().line, peek().col);
                    p->name = advance().value;
                    arrow->params.push_back(std::move(p));
                    if (!match(TokenKind::Comma)) break;
                }
                expect(TokenKind::RParen, ")");
            } else {
                auto p = makeNode(NodeKind::Identifier, peek().line, peek().col);
                p->name = advance().value;
                arrow->params.push_back(std::move(p));
            }
            expect(TokenKind::Arrow, "=>");
            if (check(TokenKind::LBrace))
                arrow->body.push_back(parseBlockStmt());
            else {
                inExpressionContext_ = true;
                arrow->body.push_back(parseAssignExpr());
                inExpressionContext_ = false;
            }
            return arrow;
        }
        case TokenKind::KW_new: {
            advance();
            auto n = makeNode(NodeKind::NewExpr, t.line, t.col);
            n->callee = parseCallMemberExpr();
            if (match(TokenKind::LParen)) {
                while (!check(TokenKind::RParen) && !atEnd()) {
                    n->arguments.push_back(parseAssignExpr());
                    if (!match(TokenKind::Comma)) break;
                }
                expect(TokenKind::RParen, ")");
            }
            return n;
        }
        default:
            error("Unexpected token '" + t.value + "'");
            return nullptr; // unreachable
    }
}

NodePtr Parser::parseFunctionExpr(bool isAsync) {
    const Token& start = expect(TokenKind::KW_function, "function");
    auto n = makeNode(NodeKind::FunctionDecl, start.line, start.col);
    n->async_ = isAsync;
    if (check(TokenKind::Identifier)) n->name = advance().value;
    expect(TokenKind::LParen, "(");
    while (!check(TokenKind::RParen) && !atEnd()) {
        auto p = makeNode(NodeKind::Identifier, peek().line, peek().col);
        if (match(TokenKind::DotDotDot)) p->name = "...";
        p->name += advance().value;
        n->params.push_back(std::move(p));
        if (!match(TokenKind::Comma)) break;
    }
    expect(TokenKind::RParen, ")");
    n->body.push_back(parseBlockStmt());
    return n;
}

NodePtr Parser::parseArrayExpr() {
    const Token& start = expect(TokenKind::LBracket, "[");
    auto n = makeNode(NodeKind::ArrayExpr, start.line, start.col);
    while (!check(TokenKind::RBracket) && !atEnd()) {
        if (match(TokenKind::DotDotDot)) {
            auto sp = makeNode(NodeKind::SpreadElement, peek().line, peek().col);
            sp->object = parseAssignExpr();
            n->children.push_back(std::move(sp));
        } else {
            n->children.push_back(parseAssignExpr());
        }
        if (!match(TokenKind::Comma)) break;
    }
    expect(TokenKind::RBracket, "]");
    return n;
}

NodePtr Parser::parseObjectExpr() {
    const Token& start = expect(TokenKind::LBrace, "{");
    auto n = makeNode(NodeKind::ObjectExpr, start.line, start.col);
    while (!check(TokenKind::RBrace) && !atEnd()) {
        auto prop = makeNode(NodeKind::ObjectProperty, peek().line, peek().col);
        if (match(TokenKind::DotDotDot)) {
            prop->name = "...";
            prop->init  = parseAssignExpr();
        } else {
            prop->name = advance().value; // key
            if (match(TokenKind::Colon)) {
                prop->init = parseAssignExpr();
            } else {
                // shorthand { x }
                auto id = makeNode(NodeKind::Identifier, prop->line, prop->col);
                id->name = prop->name;
                prop->init = std::move(id);
            }
        }
        n->children.push_back(std::move(prop));
        if (!match(TokenKind::Comma)) break;
    }
    expect(TokenKind::RBrace, "}");
    return n;
}

NodePtr Parser::parseTemplateLiteral() {
    const Token& start = advance(); // TemplateString token (lexer baked it in)
    auto n = makeNode(NodeKind::TemplateLiteral, start.line, start.col);
    // The lexer baked the whole template including ${} into one token value.
    // Store raw value; codegen re-emits as backtick string.
    n->value = start.value;
    return n;
}

// ---------------------------------------------------------------------------
// JSX parsers
// ---------------------------------------------------------------------------

// Returns the tag name string, handling Foo.Bar member expressions.
std::string Parser::parseJSXTagName() {
    std::string name = expect(TokenKind::Identifier, "JSX tag name").value;
    while (check(TokenKind::Dot)) {
        advance();
        name += "." + expect(TokenKind::Identifier, "JSX member name").value;
    }
    return name;
}

NodePtr Parser::parseJSXElement() {
    const Token& lt = expect(TokenKind::JSXLess, "<");

    // Check if the very next thing is a closing tag — shouldn't happen at top
    // level but guard anyway.
    std::string tagName = parseJSXTagName();

    auto opening = makeNode(NodeKind::JSXOpeningElement, lt.line, lt.col);
    opening->name = tagName;

    // Parse attributes
    while (!check(TokenKind::JSXGreater) && !check(TokenKind::JSXSlashGreater) && !atEnd()) {
        opening->attributes.push_back(parseJSXAttribute());
    }

    if (match(TokenKind::JSXSlashGreater)) {
        // Self-closing <Tag />
        opening->selfClosing = true;
        auto el = makeNode(NodeKind::JSXElement, lt.line, lt.col);
        el->openingElement = std::move(opening);
        el->selfClosing    = true;
        return el;
    }

    expect(TokenKind::JSXGreater, ">");

    // Children
    auto el = makeNode(NodeKind::JSXElement, lt.line, lt.col);
    el->openingElement = std::move(opening);
    el->children       = parseJSXChildren();

    // Closing tag
    auto closing = parseJSXClosingElement();
    if (closing->name != tagName) {
        throw ParseError("Mismatched JSX tags: <" + tagName + "> closed by </" + closing->name + ">",
                         closing->line, closing->col);
    }
    el->closingElement = std::move(closing);
    return el;
}

NodePtr Parser::parseJSXFragment() {
    const Token& lt = expect(TokenKind::JSXLess, "<");
    expect(TokenKind::JSXGreater, ">");

    auto frag = makeNode(NodeKind::JSXFragment, lt.line, lt.col);
    frag->children = parseJSXChildren();

    // Closing </>
    expect(TokenKind::JSXLessSlash, "</");
    expect(TokenKind::JSXGreater, ">");
    return frag;
}

NodeList Parser::parseJSXChildren() {
    NodeList children;
    while (!atEnd()) {
        if (check(TokenKind::JSXLessSlash)) break; // </Tag>

        if (check(TokenKind::JSXText)) {
            const Token& t = advance();
            // Skip whitespace-only text nodes
            bool allSpace = true;
            for (char c : t.value) if (!std::isspace((unsigned char)c)) { allSpace = false; break; }
            if (!allSpace) {
                auto txt = makeNode(NodeKind::JSXText, t.line, t.col);
                txt->value = t.value;
                children.push_back(std::move(txt));
            }
        } else if (check(TokenKind::LBrace)) {
            children.push_back(parseJSXExprContainer());
        } else if (check(TokenKind::JSXLess)) {
            // Nested element or fragment
            if (peek(1).kind == TokenKind::JSXGreater)
                children.push_back(parseJSXFragment());
            else
                children.push_back(parseJSXElement());
        } else {
            break;
        }
    }
    return children;
}

NodePtr Parser::parseJSXClosingElement() {
    const Token& ls = expect(TokenKind::JSXLessSlash, "</");
    auto n = makeNode(NodeKind::JSXClosingElement, ls.line, ls.col);
    n->name = parseJSXTagName();
    expect(TokenKind::JSXGreater, ">");
    return n;
}

NodePtr Parser::parseJSXAttribute() {
    // Spread: {...obj}
    if (check(TokenKind::LBrace)) {
        advance();
        expect(TokenKind::DotDotDot, "...");
        auto n = makeNode(NodeKind::JSXSpreadAttribute, peek().line, peek().col);
        n->expression = parseAssignExpr();
        expect(TokenKind::RBrace, "}");
        return n;
    }

    auto n = makeNode(NodeKind::JSXAttribute, peek().line, peek().col);
    n->name = expect(TokenKind::Identifier, "attribute name").value;
    // Optional: attr-name can contain '-' (data-x) — handled as separate tokens;
    // for MVP we only handle simple identifiers.

    if (!match(TokenKind::Equals)) {
        // Boolean attribute: <Tag disabled />
        auto bval = makeNode(NodeKind::BoolLiteral, n->line, n->col);
        bval->boolVal = true;
        n->init = std::move(bval);
        return n;
    }

    if (check(TokenKind::JSXString)) {
        auto sv = makeNode(NodeKind::StringLiteral, peek().line, peek().col);
        sv->value = advance().value;
        n->init = std::move(sv);
    } else if (check(TokenKind::LBrace)) {
        n->init = parseJSXExprContainer();
    } else {
        error("Expected attribute value");
    }
    return n;
}

NodePtr Parser::parseJSXExprContainer() {
    const Token& lb = expect(TokenKind::LBrace, "{");
    auto n = makeNode(NodeKind::JSXExpressionContainer, lb.line, lb.col);
    inExpressionContext_ = true;
    n->expression = parseAssignExpr();
    inExpressionContext_ = false;
    expect(TokenKind::RBrace, "}");
    return n;
}

#include "codegen.h"
#include "diagnostics.h"
#include <sstream>
#include <stdexcept>

// ---------------------------------------------------------------------------
// Construction
// ---------------------------------------------------------------------------
CodeGen::CodeGen(int indent_width) : indentWidth_(indent_width) {}

// ---------------------------------------------------------------------------
// Emit helpers
// ---------------------------------------------------------------------------
void CodeGen::emit(const std::string& s)     { out_ += s; }
void CodeGen::emitLine(const std::string& s) { out_ += s + "\n"; }
void CodeGen::indent()  { ++indentLevel_; }
void CodeGen::dedent()  { if (indentLevel_ > 0) --indentLevel_; }

std::string CodeGen::indentStr() const {
    return std::string(indentLevel_ * indentWidth_, ' ');
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------
std::string CodeGen::generate(const Node& program) {
    out_.clear();
    indentLevel_ = 0;
    genProgram(program);
    return out_;
}

// ---------------------------------------------------------------------------
// String escaping
// ---------------------------------------------------------------------------
std::string CodeGen::escapeString(const std::string& s) {
    std::string out;
    for (char c : s) {
        switch (c) {
            case '"':  out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n";  break;
            case '\r': out += "\\r";  break;
            case '\t': out += "\\t";  break;
            default:   out += c;
        }
    }
    return out;
}

// Trim leading/trailing whitespace, collapse internal runs to a single space.
std::string CodeGen::escapeJSXText(const std::string& raw) {
    std::string s;
    bool        prevSpace = true;
    for (char c : raw) {
        if (std::isspace((unsigned char)c)) {
            if (!prevSpace) { s += ' '; prevSpace = true; }
        } else {
            s += c;
            prevSpace = false;
        }
    }
    if (!s.empty() && s.back() == ' ') s.pop_back();
    return s;
}

// ---------------------------------------------------------------------------
// Dispatch
// ---------------------------------------------------------------------------
void CodeGen::genNode(const Node& n) {
    switch (n.kind) {
        // statements
        case NodeKind::Program:          genProgram(n);          break;
        case NodeKind::ImportDecl:       genImportDecl(n);       break;
        case NodeKind::ExportDefaultDecl:genExportDefaultDecl(n);break;
        case NodeKind::ExportNamedDecl:  genExportNamedDecl(n);  break;
        case NodeKind::FunctionDecl:     genFunctionDecl(n);     break;
        case NodeKind::BlockStmt:        genBlockStmt(n);        break;
        case NodeKind::ReturnStmt:       genReturnStmt(n);       break;
        case NodeKind::IfStmt:           genIfStmt(n);           break;
        case NodeKind::ForStmt:          genForStmt(n);          break;
        case NodeKind::WhileStmt:        genWhileStmt(n);        break;
        case NodeKind::VarDecl:          genVarDecl(n);          break;
        case NodeKind::ExprStmt:         genExprStmt(n);         break;
        // expressions
        default:                         genExpr(n);             break;
    }
}

void CodeGen::genProgram(const Node& n) {
    for (const auto& stmt : n.body) {
        emit(indentStr());
        genNode(*stmt);
        emitLine();
    }
}

// ---------------------------------------------------------------------------
// Statements
// ---------------------------------------------------------------------------
void CodeGen::genImportDecl(const Node& n) {
    emit("import ");
    if (n.specifiers.empty()) {
        // import "side-effect"
    } else if (n.specifiers.size() == 1 && n.specifiers[0]->name == "*") {
        emit("* as " + n.specifiers[0]->value);
    } else {
        bool first = true;
        bool hasDefault = false;
        // First check for default (no alias, no '{')
        // Simple approach: emit as-is
        emit("{ ");
        for (const auto& s : n.specifiers) {
            if (!first) emit(", ");
            first = false;
            emit(s->name);
            if (!s->value.empty()) emit(" as " + s->value);
        }
        emit(" }");
    }
    if (!n.source.empty()) emit(" from \"" + n.source + "\"");
    emit(";");
}

void CodeGen::genExportDefaultDecl(const Node& n) {
    emit("export default ");
    genNode(*n.declaration);
}

void CodeGen::genExportNamedDecl(const Node& n) {
    emit("export ");
    genNode(*n.declaration);
}

void CodeGen::genFunctionDecl(const Node& n) {
    if (n.async_) emit("async ");
    emit("function");
    if (!n.name.empty()) emit(" " + n.name);
    emit("(");
    for (size_t i = 0; i < n.params.size(); ++i) {
        if (i) emit(", ");
        emit(n.params[i]->name);
    }
    emit(") ");
    if (!n.body.empty()) genNode(*n.body[0]);
}

void CodeGen::genBlockStmt(const Node& n) {
    emitLine("{");
    indent();
    for (const auto& stmt : n.body) {
        emit(indentStr());
        genNode(*stmt);
        emitLine();
    }
    dedent();
    emit(indentStr() + "}");
}

void CodeGen::genReturnStmt(const Node& n) {
    emit("return");
    if (n.expression) { emit(" "); genExpr(*n.expression); }
    emit(";");
}

void CodeGen::genIfStmt(const Node& n) {
    emit("if ("); genExpr(*n.test); emit(") ");
    genNode(*n.consequent);
    if (n.alternate) { emit(" else "); genNode(*n.alternate); }
}

void CodeGen::genForStmt(const Node& n) {
    emit("for (");
    if (n.init)   genNode(*n.init);  else emit(";");
    emit(" ");
    if (n.test)   genExpr(*n.test);
    emit("; ");
    if (n.update) genExpr(*n.update);
    emit(") ");
    if (!n.body.empty()) genNode(*n.body[0]);
}

void CodeGen::genWhileStmt(const Node& n) {
    emit("while ("); genExpr(*n.test); emit(") ");
    if (!n.body.empty()) genNode(*n.body[0]);
}

void CodeGen::genVarDecl(const Node& n) {
    emit(n.varKind + " ");
    for (size_t i = 0; i < n.declarations.size(); ++i) {
        if (i) emit(", ");
        const Node& d = *n.declarations[i];
        emit(d.name);
        if (d.init) { emit(" = "); genExpr(*d.init); }
    }
    emit(";");
}

void CodeGen::genExprStmt(const Node& n) {
    genExpr(*n.expression);
    emit(";");
}

// ---------------------------------------------------------------------------
// Expressions
// ---------------------------------------------------------------------------
void CodeGen::genExpr(const Node& n) {
    switch (n.kind) {
        case NodeKind::Identifier:          genIdentifier(n);       break;
        case NodeKind::NumericLiteral:      genNumericLiteral(n);   break;
        case NodeKind::StringLiteral:       genStringLiteral(n);    break;
        case NodeKind::TemplateLiteral:     genTemplateLiteral(n);  break;
        case NodeKind::BoolLiteral:         genBoolLiteral(n);      break;
        case NodeKind::NullLiteral:         emit("null");            break;
        case NodeKind::BinaryExpr:          genBinaryExpr(n);       break;
        case NodeKind::UnaryExpr:           genUnaryExpr(n);        break;
        case NodeKind::LogicalExpr:         genLogicalExpr(n);      break;
        case NodeKind::AssignExpr:          genAssignExpr(n);       break;
        case NodeKind::CallExpr:            genCallExpr(n);         break;
        case NodeKind::MemberExpr:          genMemberExpr(n);       break;
        case NodeKind::NewExpr:             genNewExpr(n);          break;
        case NodeKind::ConditionalExpr:     genConditionalExpr(n);  break;
        case NodeKind::SpreadElement:       genSpreadElement(n);    break;
        case NodeKind::ArrayExpr:           genArrayExpr(n);        break;
        case NodeKind::ObjectExpr:          genObjectExpr(n);       break;
        case NodeKind::ArrowFunctionExpr:   genArrowFunctionExpr(n);break;
        case NodeKind::SequenceExpr:        genSequenceExpr(n);     break;
        case NodeKind::JSXElement:          genJSXElement(n);       break;
        case NodeKind::JSXFragment:         genJSXFragment(n);      break;
        // Statements that can appear as expressions (function exprs etc.)
        case NodeKind::FunctionDecl:        genFunctionDecl(n);     break;
        default:
            throw CodeGenError("Unhandled expression node kind " +
                               std::to_string(static_cast<int>(n.kind)));
    }
}

void CodeGen::genIdentifier(const Node& n)     { emit(n.name); }
void CodeGen::genNumericLiteral(const Node& n) { emit(n.value); }
void CodeGen::genStringLiteral(const Node& n)  { emit("\"" + escapeString(n.value) + "\""); }
void CodeGen::genBoolLiteral(const Node& n)    { emit(n.boolVal ? "true" : "false"); }

void CodeGen::genTemplateLiteral(const Node& n) {
    // The lexer stored the raw content (between backticks) in n.value.
    emit("`" + n.value + "`");
}

void CodeGen::genBinaryExpr(const Node& n) {
    emit("("); genExpr(*n.object); emit(" " + n.name + " "); genExpr(*n.property); emit(")");
}

void CodeGen::genUnaryExpr(const Node& n) {
    std::string op = n.name;
    bool isPost = op.size() > 4 && op.substr(op.size() - 4) == "post";
    bool isPre  = op.size() > 3 && op.substr(op.size() - 3) == "pre";
    if (isPre) {
        emit(op.substr(0, op.size() - 3));
        genExpr(*n.object);
    } else if (isPost) {
        genExpr(*n.object);
        emit(op.substr(0, op.size() - 4));
    } else {
        emit(op + " ");
        genExpr(*n.object);
    }
}

void CodeGen::genLogicalExpr(const Node& n)  { genBinaryExpr(n); }
void CodeGen::genAssignExpr(const Node& n)   {
    genExpr(*n.object); emit(" " + n.name + " "); genExpr(*n.property);
}

void CodeGen::genCallExpr(const Node& n) {
    genExpr(*n.callee);
    emit("(");
    for (size_t i = 0; i < n.arguments.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.arguments[i]);
    }
    emit(")");
}

void CodeGen::genMemberExpr(const Node& n) {
    genExpr(*n.object);
    if (n.computed) { emit("["); genExpr(*n.property); emit("]"); }
    else             { emit("."); genExpr(*n.property); }
}

void CodeGen::genNewExpr(const Node& n) {
    emit("new ");
    genExpr(*n.callee);
    emit("(");
    for (size_t i = 0; i < n.arguments.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.arguments[i]);
    }
    emit(")");
}

void CodeGen::genConditionalExpr(const Node& n) {
    emit("(");
    genExpr(*n.test); emit(" ? "); genExpr(*n.consequent); emit(" : "); genExpr(*n.alternate);
    emit(")");
}

void CodeGen::genSpreadElement(const Node& n) { emit("..."); genExpr(*n.object); }

void CodeGen::genArrayExpr(const Node& n) {
    emit("[");
    for (size_t i = 0; i < n.children.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.children[i]);
    }
    emit("]");
}

void CodeGen::genObjectExpr(const Node& n) {
    emit("{ ");
    for (size_t i = 0; i < n.children.size(); ++i) {
        if (i) emit(", ");
        const Node& prop = *n.children[i];
        if (prop.name == "...") { emit("..."); genExpr(*prop.init); }
        else {
            emit(prop.name + ": ");
            genExpr(*prop.init);
        }
    }
    emit(" }");
}

void CodeGen::genArrowFunctionExpr(const Node& n) {
    if (n.async_) emit("async ");
    emit("(");
    for (size_t i = 0; i < n.params.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.params[i]);
    }
    emit(") => ");
    if (!n.body.empty()) {
        if (n.body[0]->kind == NodeKind::BlockStmt)
            genBlockStmt(*n.body[0]);
        else
            genExpr(*n.body[0]);
    }
}

void CodeGen::genSequenceExpr(const Node& n) {
    for (size_t i = 0; i < n.children.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.children[i]);
    }
}

// ---------------------------------------------------------------------------
// JSX lowering
// ---------------------------------------------------------------------------

// Emit the second argument to React.createElement: props object or null.
void CodeGen::emitJSXProps(const Node& openingEl) {
    if (openingEl.attributes.empty()) {
        emit("null");
        return;
    }
    emit("{ ");
    bool first = true;
    for (const auto& attrPtr : openingEl.attributes) {
        const Node& attr = *attrPtr;
        if (!first) emit(", ");
        first = false;

        if (attr.kind == NodeKind::JSXSpreadAttribute) {
            emit("...");
            genExpr(*attr.expression);
        } else {
            emit(attr.name + ": ");
            if (attr.init) {
                if (attr.init->kind == NodeKind::JSXExpressionContainer)
                    genExpr(*attr.init->expression);
                else
                    genExpr(*attr.init);
            } else {
                emit("true");
            }
        }
    }
    emit(" }");
}

void CodeGen::genJSXElement(const Node& n) {
    const Node& opening = *n.openingElement;
    emit("React.createElement(");

    // First arg: tag name (string for lowercase, identifier for uppercase/member)
    char firstChar = opening.name.empty() ? '\0' : opening.name[0];
    if (std::islower((unsigned char)firstChar)) {
        emit("\"" + opening.name + "\"");
    } else {
        emit(opening.name);
    }

    emit(", ");
    emitJSXProps(opening);

    // Children
    for (const auto& child : n.children) {
        emit(", ");
        genJSXChild(*child);
    }

    emit(")");
}

void CodeGen::genJSXFragment(const Node& n) {
    emit("React.createElement(React.Fragment, null");
    for (const auto& child : n.children) {
        emit(", ");
        genJSXChild(*child);
    }
    emit(")");
}

void CodeGen::genJSXChild(const Node& n) {
    if (n.kind == NodeKind::JSXText) {
        std::string text = escapeJSXText(n.value);
        if (!text.empty()) emit("\"" + escapeString(text) + "\"");
    } else if (n.kind == NodeKind::JSXExpressionContainer) {
        genExpr(*n.expression);
    } else if (n.kind == NodeKind::JSXElement) {
        genJSXElement(n);
    } else if (n.kind == NodeKind::JSXFragment) {
        genJSXFragment(n);
    } else {
        genExpr(n);
    }
}

#include "lexer.h"
#include "parser.h"
#include "codegen.h"
#include "diagnostics.h"

#include <fstream>
#include <iostream>
#include <sstream>
#include <string>

static void printUsage(const char* argv0) {
    std::cerr << "Usage: " << argv0 << " [options] <input.jsx>\n"
              << "Options:\n"
              << "  -o <file>    Write output to file (default: stdout)\n"
              << "  -h           Show this help\n";
}

static std::string readFile(const std::string& path) {
    std::ifstream f(path);
    if (!f) {
        std::cerr << "error: cannot open '" << path << "'\n";
        std::exit(1);
    }
    std::ostringstream ss;
    ss << f.rdbuf();
    return ss.str();
}

int main(int argc, char** argv) {
    std::string inputPath;
    std::string outputPath;

    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        if (arg == "-h" || arg == "--help") {
            printUsage(argv[0]);
            return 0;
        } else if (arg == "-o") {
            if (++i >= argc) { std::cerr << "error: -o requires a filename\n"; return 1; }
            outputPath = argv[i];
        } else if (arg[0] == '-') {
            std::cerr << "error: unknown option '" << arg << "'\n";
            printUsage(argv[0]);
            return 1;
        } else {
            if (!inputPath.empty()) {
                std::cerr << "error: multiple input files not supported\n";
                return 1;
            }
            inputPath = arg;
        }
    }

    if (inputPath.empty()) {
        printUsage(argv[0]);
        return 1;
    }

    std::string source = readFile(inputPath);

    try {
        Lexer lexer(source);
        auto tokens = lexer.tokenize();

        Parser parser(std::move(tokens));
        auto ast = parser.parse();

        CodeGen gen;
        std::string output = gen.generate(*ast);

        if (outputPath.empty()) {
            std::cout << output;
        } else {
            std::ofstream out(outputPath);
            if (!out) {
                std::cerr << "error: cannot write to '" << outputPath << "'\n";
                return 1;
            }
            out << output;
        }

    } catch (const LexError& e) {
        std::cerr << formatDiag("lex error", e.what(), e.line, e.col) << "\n";
        return 1;
    } catch (const ParseError& e) {
        std::cerr << formatDiag("parse error", e.what(), e.line, e.col) << "\n";
        return 1;
    } catch (const CodeGenError& e) {
        std::cerr << "codegen error: " << e.what() << "\n";
        return 1;
    } catch (const std::exception& e) {
        std::cerr << "error: " << e.what() << "\n";
        return 1;
    }

    return 0;
}

export default function App() {
  return <div />;
}

export function App() {
  return React.createElement("div", null);
}

export default function App() {
  return <div></div>;
}

export function App() {
  return React.createElement("div", null);
}

